/**
 * Konstanta Pembobotan dan Parameter Operasional Rule-Based Scoring 5 Langkah (Dual-Mode)
 */

// Vektor Bobot Kriteria (W): Total = 1.00 (100%)
export const WEIGHTS = {
  uv: 0.25,          // C1: Proteksi UV (25%)
  skinType: 0.25,    // C2: Jenis Kulit (25%)
  activity: 0.20,    // C3: Aktivitas Harian (20%)
  skinConcern: 0.10, // C4: Masalah Kulit (10%)
  texture: 0.10,     // C5: Preferensi Tekstur (10%)
  finish: 0.10,      // C6: Hasil Akhir (10%)
};

// Target Proteksi Rutin (Penggunaan Berulang / Standar Tropis Statis)
export const TARGET_ROUTINE = {
  spf: 30,
  pa: 'PA+++',
};

// Target Proteksi Hari Ini Berdasarkan Kategori Risiko Indeks UV (Tabel 3 Metodologi)
export function getTodayTarget(uvIndex: number): { spf: number; pa: string } {
  if (uvIndex < 6) {
    // 0 <= UV < 3 (Rendah) dan 3 <= UV < 6 (Sedang)
    return { spf: 30, pa: 'PA+++' };
  } else if (uvIndex < 8) {
    // 6 <= UV < 8 (Tinggi)
    return { spf: 50, pa: 'PA+++' };
  } else {
    // UV >= 8 (Sangat Tinggi & Ekstrem)
    return { spf: 50, pa: 'PA++++' };
  }
}

// Kelompok Sediaan Tekstur Serumpun (C5)
export const TEXTURE_GROUPS: string[][] = [
  ['gel', 'serum', 'watery'],
  ['cream', 'lotion', 'milk'],
  ['spray', 'mist'],
  ['stick'],
];

// Pasangan Hasil Akhir Bertetangga pada Spektrum Kosmetik (C6)
export const FINISH_NEIGHBORS: Record<string, string[]> = {
  'matte': ['natural'],
  'natural': ['matte', 'dewy'],
  'dewy': ['natural'],
  'tone_up': [], // Tone-Up berdiri sebagai kategori tersendiri
};

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

import { mapSkinTypeCode } from "./utils.ts";

export interface SkinProfileResult {
  skinTypeData?: any;
  skinConcernsData?: any[];
  error?: string;
  statusCode?: number;
}

export async function fetchSkinProfile(
  adminClient: any,
  skinTypeId: string,
  skinConcernIds: string[]
): Promise<SkinProfileResult> {
  const { data: skinTypeData, error: skinTypeError } = await adminClient
    .from('skin_types')
    .select('skin_type_code, skin_type_name')
    .eq('skin_type_id', skinTypeId)
    .single();

  if (skinTypeError || !skinTypeData) {
    return {
      error: "Jenis kulit tidak ditemukan di database",
      statusCode: 400
    };
  }

  let skinConcernsData: any[] = [];
  if (skinConcernIds && skinConcernIds.length > 0) {
    const { data: concernsData, error: skinConcernsError } = await adminClient
      .from('skin_concerns')
      .select('skin_concern_id, skin_concern_code, skin_concern_name')
      .in('skin_concern_id', skinConcernIds);

    if (skinConcernsError || !concernsData) {
      return {
        error: "Gagal mengambil data masalah kulit dari database",
        statusCode: 400
      };
    }
    skinConcernsData = concernsData;
  }

  return { skinTypeData, skinConcernsData };
}


export interface ActiveProductsResult {
  products?: any[];
  error?: string;
  statusCode?: number;
}

export async function fetchActiveProducts(adminClient: any): Promise<ActiveProductsResult> {
  const { data: products, error: productsError } = await adminClient
    .from('products')
    .select(`
      *,
      product_skin_types (skin_type_id),
      product_skin_concerns (skin_concern_id),
      product_ingredients (
        ingredient_id,
        ingredients (ingredient_code)
      )
    `)
    .eq('is_active', true);

  if (productsError || !products || products.length === 0) {
    return {
      error: "Tidak ada produk aktif yang tersedia di database",
      statusCode: 404
    };
  }
  return { products };
}

export async function fetchAllSkinTypesMap(adminClient: any): Promise<Map<string, string>> {
  const { data: allSkinTypes } = await adminClient
    .from('skin_types')
    .select('skin_type_id, skin_type_code, skin_type_name');
  const skinTypeMap = new Map<string, string>();
  if (allSkinTypes) {
    for (const st of allSkinTypes) {
      skinTypeMap.set(st.skin_type_id, mapSkinTypeCode(st.skin_type_code || st.skin_type_name));
    }
  }
  return skinTypeMap;
}

export async function fetchAllSkinConcernsMap(adminClient: any): Promise<Map<string, string>> {
  const { data: allConcerns } = await adminClient
    .from('skin_concerns')
    .select('skin_concern_id, skin_concern_code');
  const concernMap = new Map<string, string>();
  if (allConcerns) {
    for (const sc of allConcerns) {
      concernMap.set(sc.skin_concern_id, sc.skin_concern_code);
    }
  }
  return concernMap;
}

export interface TransactionResult {
  transactionRes?: any;
  error?: string;
  statusCode?: number;
}

export async function saveRecommendationTransaction(
  adminClient: any,
  params: {
    userId: string;
    skinTypeId: string;
    activity: string;
    texturePreference?: string | null;
    finishPreference?: string | null;
    allergyStatus: string;
    usageTimePreference: string;
    locationName?: string | null;
    latitude: number;
    longitude: number;
    uvIndex: number;
    skinConcernIds: string[];
    avoidedIngredientIds: string[];
    rankedProducts: any[];
  }
): Promise<TransactionResult> {
  const { data: transactionRes, error: transactionError } = await adminClient.rpc('save_recommendation_transaction', {
    p_user_id: params.userId,
    p_skin_type_id: params.skinTypeId,
    p_activity: params.activity,
    p_texture_preference: params.texturePreference || null,
    p_finish_preference: params.finishPreference || null,
    p_allergy_status: params.allergyStatus,
    p_usage_time_preference: params.usageTimePreference,
    p_location_name: params.locationName || null,
    p_latitude: params.latitude,
    p_longitude: params.longitude,
    p_uv_index: params.uvIndex,
    p_skin_concern_ids: params.skinConcernIds,
    p_avoided_ingredient_ids: params.avoidedIngredientIds || [],
    p_results: params.rankedProducts.map(item => ({
      product_id: item.product.product_id,
      match_score: item.finalScore,
      recommendation_category: item.category,
      rank_position: item.rank_position,
      skin_type_score: item.maxSkinTypeScore,
      activity_score: item.activityScore,
      skin_concern_score: item.skinConcernScore,
      texture_score: item.textureScore,
      finish_score: item.finishScore,
      penalty: item.penalty
    }))
  });

  if (transactionError || !transactionRes) {
    return {
      error: `Gagal menyimpan hasil rekomendasi: ${transactionError?.message || 'Unknown error'}`,
      statusCode: 500
    };
  }

  return { transactionRes };
}

// @ts-nocheck
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.8";
import { corsHeaders } from "./cors.ts";
import {
  mapSkinTypeCode,
  mapConcernCode,
} from "./utils.ts";
import {
  evaluateProduct,
} from "./scoring.ts";
import {
  TARGET_ROUTINE,
} from "./constants.ts";
import {
  validateRequestBody,
  validateUsageTimePreference,
} from "./validation.ts";
import { getUvDataAndThresholds } from "./uv_service.ts";
import {
  fetchSkinProfile,
  fetchActiveProducts,
  fetchAllSkinTypesMap,
  fetchAllSkinConcernsMap,
  saveRecommendationTransaction,
} from "./db_service.ts";

Deno.serve(async (req) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    if (req.method !== 'POST') {
      return new Response(JSON.stringify({ error: "Method not allowed" }), {
        status: 405,
        headers: { ...corsHeaders, "Content-Type": "application/json" }
      });
    }

    const body = await req.json().catch(() => ({}));

    // --- Authentication / User ID ---
    const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
    const supabaseAnonKey = Deno.env.get('SUPABASE_ANON_KEY') ?? '';
    const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';

    let userId = '';
    const authHeader = req.headers.get('Authorization');

    if (authHeader && authHeader !== `Bearer ${supabaseAnonKey}`) {
      const token = authHeader.replace('Bearer ', '');
      const userClient = createClient(supabaseUrl, supabaseAnonKey, {
        global: { headers: { Authorization: authHeader } }
      });

      const { data: { user }, error: authError } = await userClient.auth.getUser(token);
      if (!authError && user) {
        userId = user.id;
      }
    }

    // Postman / API testing fallback
    if (!userId) {
      userId = body.user_id;
    }
    body.user_id = userId;

    // --- Validate Request Body ---
    const validation = validateRequestBody(body);
    if (validation.error) {
      return new Response(JSON.stringify({ error: validation.error }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" }
      });
    }

    const lat = Number(body.latitude);
    const lon = Number(body.longitude);

    // --- Retrieve UV Index from Open-Meteo & Thresholds ---
    let uvData;
    try {
      uvData = await getUvDataAndThresholds(lat, lon, body.usage_time_preference);
    } catch (err: any) {
      return new Response(JSON.stringify({ error: err.message }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" }
      });
    }

    const {
      uvIndex,
      uvRiskLevel,
      spfMinimum,
      paMinimum,
      usageTimePref,
      isForecast,
      isNight
    } = uvData;

    // --- Validate Sunscreen Usage Time Preference (Night flow checking) ---
    const usageTimeValidation = validateUsageTimePreference(body.usage_time_preference, isNight);
    if (usageTimeValidation.error) {
      return new Response(JSON.stringify({ error: usageTimeValidation.error }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" }
      });
    }

    // --- Initialize Database Client ---
    const adminClient = createClient(supabaseUrl, serviceRoleKey);

    // --- Fetch Skin Type Details & Skin Concerns Details ---
    const skinProfile = await fetchSkinProfile(adminClient, body.skin_type_id, body.skin_concern_ids);
    if (skinProfile.error) {
      return new Response(JSON.stringify({ error: skinProfile.error }), {
        status: skinProfile.statusCode || 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" }
      });
    }

    const { skinTypeData, skinConcernsData } = skinProfile;
    const userSkinCode = mapSkinTypeCode(skinTypeData.skin_type_code || skinTypeData.skin_type_name);
    const userConcernCodes = (skinConcernsData || []).map(item => mapConcernCode(item.skin_concern_code || item.skin_concern_name));

    // --- Fetch Active Products with Relations ---
    const activeProductsRes = await fetchActiveProducts(adminClient);
    if (activeProductsRes.error) {
      return new Response(JSON.stringify({ error: activeProductsRes.error }), {
        status: activeProductsRes.statusCode || 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" }
      });
    }

    const products = activeProductsRes.products!;

    // Map all skin types & concerns for ID-to-code lookup
    const skinTypeMap = await fetchAllSkinTypesMap(adminClient);
    const skinConcernMap = await fetchAllSkinConcernsMap(adminClient);

    // --- Evaluasi Skor Produk Sunscreen untuk Kedua Mode (Murni 6 Kriteria Berbobot) ---
    const routineCandidates = [];
    const todayCandidates = [];

    for (const product of products) {

      const productSkinCodes = product.product_skin_types
        ?.map((pst: any) => skinTypeMap.get(pst.skin_type_id))
        .filter(Boolean) || [];

      const productConcernCodes = product.product_skin_concerns
        ?.map((psc: any) => skinConcernMap.get(psc.skin_concern_id))
        .filter(Boolean) || [];

      // ─────────────────────────────────────
      // MODE 1: REKOMENDASI RUTIN (Standar Tropis SPF 30 PA+++)
      // ─────────────────────────────────────
      const evalRoutine = evaluateProduct(
        product,
        userSkinCode,
        userConcernCodes,
        body.activity,
        body.texture_preference,
        body.finish_preference,
        TARGET_ROUTINE.spf,
        TARGET_ROUTINE.pa,
        productSkinCodes,
        productConcernCodes
      );

      if (evalRoutine.isEligible) {
        routineCandidates.push({
          product,
          eval: evalRoutine,
          finalScore: evalRoutine.finalScore,
        });
      }

      // ─────────────────────────────────────
      // MODE 2: REKOMENDASI HARI INI (Sesuai Indeks UV Cuaca Open-Meteo)
      // ─────────────────────────────────────
      const evalToday = evaluateProduct(
        product,
        userSkinCode,
        userConcernCodes,
        body.activity,
        body.texture_preference,
        body.finish_preference,
        spfMinimum,
        paMinimum,
        productSkinCodes,
        productConcernCodes
      );

      if (evalToday.isEligible) {
        todayCandidates.push({
          product,
          eval: evalToday,
          finalScore: evalToday.finalScore,
        });
      }
    }

    // --- Ranking & Top 3 Selection untuk Kedua Mode ---
    routineCandidates.sort((a, b) => b.finalScore - a.finalScore || a.product.product_name.localeCompare(b.product.product_name));
    todayCandidates.sort((a, b) => b.finalScore - a.finalScore || a.product.product_name.localeCompare(b.product.product_name));

    const topRoutine = routineCandidates.slice(0, 3).map((item, index) => ({
      ...item,
      rank_position: index + 1,
    }));

    const topToday = todayCandidates.slice(0, 3).map((item, index) => ({
      ...item,
      rank_position: index + 1,
    }));

    if (topRoutine.length === 0 && topToday.length === 0) {
      return new Response(JSON.stringify({ error: "Rekomendasi yang sesuai belum tersedia untuk kondisi saat ini." }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" }
      });
    }

    // Helper formatter untuk output produk
    const formatProductOutput = (item: any) => ({
      rank_position: item.rank_position,
      product_id: item.product.product_id,
      product_code: item.product.product_code,
      brand_name: item.product.brand_name,
      product_name: item.product.product_name,
      bpom_number: item.product.bpom_number,
      spf: item.product.spf,
      pa_grade: item.product.pa_grade,
      sunscreen_type: item.product.sunscreen_type,
      texture: item.product.texture,
      finish: item.product.finish,
      match_score: item.eval.finalScore,
      recommendation_category: item.eval.category,
      // 6 Nilai Kecocokan Kriteria (s_ij)
      s_uv: item.eval.s_uv,
      s_skin: item.eval.s_skin,
      s_activity: item.eval.s_activity,
      s_concern: item.eval.s_concern,
      s_texture: item.eval.s_texture,
      s_finish: item.eval.s_finish,
      // Persentase Kontribusi Relatif K_ij (Persamaan 2 - Total 100%)
      contributions: item.eval.contributions,
      // Skor Poin Terbobot (Kompatibilitas Tampilan Lama)
      uv_score: Math.round(item.eval.s_uv * 25),
      skin_type_score: Math.round(item.eval.s_skin * 25),
      activity_score: Math.round(item.eval.s_activity * 20),
      skin_concern_score: Math.round(item.eval.s_concern * 10),
      texture_score: Math.round(item.eval.s_texture * 10),
      finish_score: Math.round(item.eval.s_finish * 10),
      penalty: 0,
    });

    const routineFormatted = topRoutine.map(formatProductOutput);
    const todayFormatted = topToday.map(formatProductOutput);

    // Primary results to save in DB transaction (prioritaskan today, fallback ke routine)
    const primaryForTransaction = topToday.length > 0 ? topToday : topRoutine;

    // --- Save to Database via PL/pgSQL Transaction RPC ---
    const transaction = await saveRecommendationTransaction(adminClient, {
      userId: body.user_id,
      skinTypeId: body.skin_type_id,
      activity: body.activity,
      texturePreference: body.texture_preference,
      finishPreference: body.finish_preference || null,
      allergyStatus: body.allergy_status,
      usageTimePreference: usageTimePref,
      locationName: body.location_name,
      latitude: lat,
      longitude: lon,
      uvIndex: uvIndex,
      skinConcernIds: body.skin_concern_ids || [],
      avoidedIngredientIds: body.avoided_ingredient_ids || [],
      rankedProducts: primaryForTransaction.map(item => ({
        product: item.product,
        finalScore: item.eval.finalScore,
        category: item.eval.category,
        rank_position: item.rank_position,
        maxSkinTypeScore: Math.round(item.eval.s_skin * 25),
        activityScore: Math.round(item.eval.s_activity * 20),
        skinConcernScore: Math.round(item.eval.s_concern * 10),
        textureScore: Math.round(item.eval.s_texture * 10),
        finishScore: Math.round(item.eval.s_finish * 10),
        penalty: 0,
      }))
    });

    let sessionResponse = { session_id: null, recommendation_code: null };
    if (!transaction.error && transaction.transactionRes) {
      sessionResponse = transaction.transactionRes;
    }

    // --- Format Response Payload Lengkap (Dual Mode) ---
    const responsePayload = {
      recommendation_session_id: sessionResponse.session_id,
      recommendation_code: sessionResponse.recommendation_code,
      uv_data: {
        uv_index: uvIndex,
        uv_risk_level: uvRiskLevel,
        spf_minimum: spfMinimum,
        pa_minimum: paMinimum,
        routine_spf_target: TARGET_ROUTINE.spf,
        routine_pa_target: TARGET_ROUTINE.pa,
        usage_time_preference: usageTimePref,
        is_forecast: isForecast
      },
      routine_results: routineFormatted,
      today_results: todayFormatted,
      // Fallback backward-compatibility untuk client lama
      results: todayFormatted.length > 0 ? todayFormatted : routineFormatted,
    };

    return new Response(JSON.stringify(responsePayload), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" }
    });

  } catch (err: any) {
    return new Response(JSON.stringify({ error: err.message || "Terjadi kesalahan internal pada server" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" }
    });
  }
});

import { WEIGHTS, TEXTURE_GROUPS, FINISH_NEIGHBORS } from "./constants.ts";
import { comparePaGrade } from "./utils.ts";


/**
 * C1: Evaluasi Derajat Kecocokan Proteksi UV (s_i1)
 * Nilai: 1.0 jika SPF dan PA memenuhi target; 0.0 jika salah satu atau keduanya tidak memenuhi
 */
export function calculateUvProtectionScore(
  productSpf: number,
  productPa: string,
  targetSpf: number,
  targetPa: string
): number {
  const isSpfMet = productSpf >= targetSpf;
  const isPaMet = comparePaGrade(productPa, targetPa);
  return (isSpfMet && isPaMet) ? 1.0 : 0.0;
}

/**
 * C2: Evaluasi Derajat Kecocokan Jenis Kulit (s_i2)
 * Nilai:
 * - 1.0 jika klaim spesifik produk cocok dengan jenis kulit pengguna
 * - 0.6 jika produk memiliki klaim untuk semua jenis kulit (netral/normal)
 * - 0.0 jika tidak ada kecocokan yang terverifikasi
 */
export function calculateSkinTypeScore(
  userSkinCode: string,
  productSkinCodes: string[]
): number {
  if (productSkinCodes.includes(userSkinCode)) {
    return 1.0;
  }
  // Formula netral / untuk semua jenis kulit
  if (productSkinCodes.includes('normal') || productSkinCodes.includes('all_skin_types') || userSkinCode === 'normal') {
    return 0.6;
  }
  return 0.0;
}

/**
 * C3: Evaluasi Derajat Kecocokan Aktivitas Harian (s_i3)
 * Nilai:
 * - 1.0 untuk indoor & outdoor ringan (tanpa syarat ketahanan air)
 * - 1.0 untuk outdoor intensif & olahraga JIKA produk water-resistant; 0.0 jika tidak
 * - Untuk renang: 1.0 jika very water-resistant; 0.5 jika water-resistant biasa; 0.0 jika tidak
 */
export function calculateActivityScore(
  activity: string,
  product: { is_water_resistant?: boolean; is_very_water_resistant?: boolean }
): number {
  if (activity === 'indoor' || activity === 'outdoor_light') {
    return 1.0;
  }

  if (activity === 'outdoor_intense' || activity === 'sport') {
    return (product.is_water_resistant || product.is_very_water_resistant) ? 1.0 : 0.0;
  }

  if (activity === 'swim') {
    if (product.is_very_water_resistant) return 1.0;
    if (product.is_water_resistant) return 0.5;
    return 0.0;
  }

  return 0.0;
}

/**
 * C4: Evaluasi Derajat Kecocokan Masalah Kulit (s_i4)
 * Nilai:
 * - 1.0 jika seluruh masalah yang dipilih memiliki klaim pendukung atau tidak ada masalah khusus
 * - 0.5 jika sebagian masalah yang dipilih memiliki klaim pendukung
 * - 0.0 jika tidak ada klaim pendukung yang sesuai
 */
export function calculateSkinConcernScore(
  userConcernCodes: string[],
  productConcernCodes: string[],
  product: { is_non_comedogenic?: boolean; is_oil_free?: boolean }
): number {
  const activeConcerns = (userConcernCodes || []).filter(c => c && c !== 'none');
  if (activeConcerns.length === 0) {
    return 1.0;
  }

  let matchCount = 0;
  for (const concern of activeConcerns) {
    if (concern === 'acne') {
      if (
        productConcernCodes.includes('acne') ||
        product.is_non_comedogenic === true ||
        product.is_oil_free === true
      ) {
        matchCount++;
      }
    } else if (concern === 'hyperpigmentation') {
      if (productConcernCodes.includes('hyperpigmentation')) {
        matchCount++;
      }
    } else {
      if (productConcernCodes.includes(concern)) {
        matchCount++;
      }
    }
  }

  if (matchCount === activeConcerns.length) return 1.0;
  if (matchCount > 0) return 0.5;
  return 0.0;
}

/**
 * C5: Evaluasi Derajat Kecocokan Preferensi Tekstur (s_i5)
 * Nilai:
 * - 1.0 jika tekstur persis sesuai preferensi
 * - 0.5 jika tekstur berada dalam kelompok sediaan sejenis (gel-serum-watery, cream-lotion-milk, spray-mist, stick)
 * - 0.0 jika berada pada kelompok berbeda
 */
export function calculateTextureScore(
  texturePreference: string | null,
  productTexture: string
): number {
  if (!texturePreference) {
    return 1.0;
  }

  const pTex = (productTexture || '').toLowerCase();
  const uTex = texturePreference.toLowerCase();

  if (pTex === uTex) {
    return 1.0;
  }

  // Cek apakah satu kelompok serumpun
  for (const group of TEXTURE_GROUPS) {
    if (group.includes(uTex) && group.includes(pTex)) {
      return 0.5;
    }
  }

  return 0.0;
}

/**
 * C6: Evaluasi Derajat Kecocokan Hasil Akhir / Finish (s_i6)
 * Nilai:
 * - 1.0 jika hasil akhir persis sesuai preferensi
 * - 0.5 jika karakteristik berdekatan (matte <-> natural, natural <-> dewy)
 * - 0.0 jika tidak sesuai / tone-up terpisah
 */
export function calculateFinishScore(
  finishPreference: string | null,
  productFinish: string
): number {
  if (!finishPreference) {
    return 1.0;
  }

  const pFinish = (productFinish || '').toLowerCase();
  const uFinish = finishPreference.toLowerCase();

  if (pFinish === uFinish) {
    return 1.0;
  }

  const neighbors = FINISH_NEIGHBORS[uFinish] || [];
  if (neighbors.includes(pFinish)) {
    return 0.5;
  }

  return 0.0;
}

export interface EvaluationResult {
  s_uv: number;
  s_skin: number;
  s_activity: number;
  s_concern: number;
  s_texture: number;
  s_finish: number;
  finalScore: number;
  category: 'highly_recommended' | 'recommended' | 'fairly_suitable' | 'not_suitable';
  isEligible: boolean;
  contributions: {
    uv: number;
    skinType: number;
    activity: number;
    skinConcern: number;
    texture: number;
    finish: number;
  };
}

/**
 * Evaluasi Lengkap 5 Langkah untuk Satu Produk
 */
export function evaluateProduct(
  product: any,
  userSkinCode: string,
  userConcernCodes: string[],
  activity: string,
  texturePreference: string | null,
  finishPreference: string | null,
  targetSpf: number,
  targetPa: string,
  productSkinCodes: string[],
  productConcernCodes: string[]
): EvaluationResult {
  // 1. Hitung s_ij untuk keenam kriteria
  const s_uv = calculateUvProtectionScore(product.spf, product.pa_grade, targetSpf, targetPa);
  const s_skin = calculateSkinTypeScore(userSkinCode, productSkinCodes);
  const s_activity = calculateActivityScore(activity, product);
  const s_concern = calculateSkinConcernScore(userConcernCodes, productConcernCodes, product);
  const s_texture = calculateTextureScore(texturePreference, product.texture);
  const s_finish = calculateFinishScore(finishPreference, product.finish);

  // 2. Perhitungan Skor Akhir Terbobot: Final Score = 100 * sum(w_j * s_ij)
  const weightedSum =
    WEIGHTS.uv * s_uv +
    WEIGHTS.skinType * s_skin +
    WEIGHTS.activity * s_activity +
    WEIGHTS.skinConcern * s_concern +
    WEIGHTS.texture * s_texture +
    WEIGHTS.finish * s_finish;

  // Konversi ke skala 0 - 100 (dibulatkan ke integer)
  const finalScore = Math.round(weightedSum * 100);

  // 3. Kategori Kesesuaian (Tabel 4)
  let category: EvaluationResult['category'] = 'not_suitable';
  if (finalScore >= 80) {
    category = 'highly_recommended';
  } else if (finalScore >= 60) {
    category = 'recommended';
  } else if (finalScore >= 40) {
    category = 'fairly_suitable';
  }

  // 4. Seleksi Kelayakan Kandidat (Langkah 5): Skor Akhir >= 40 (Kategori Cukup Sesuai ke atas)
  const isEligible = finalScore >= 40;

  // 5. Persentase Kontribusi Relatif K_ij (Persamaan 2)
  let contributions = {
    uv: 0,
    skinType: 0,
    activity: 0,
    skinConcern: 0,
    texture: 0,
    finish: 0,
  };

  if (weightedSum > 0) {
    contributions = {
      uv: Math.round(((WEIGHTS.uv * s_uv) / weightedSum) * 1000) / 10,
      skinType: Math.round(((WEIGHTS.skinType * s_skin) / weightedSum) * 1000) / 10,
      activity: Math.round(((WEIGHTS.activity * s_activity) / weightedSum) * 1000) / 10,
      skinConcern: Math.round(((WEIGHTS.skinConcern * s_concern) / weightedSum) * 1000) / 10,
      texture: Math.round(((WEIGHTS.texture * s_texture) / weightedSum) * 1000) / 10,
      finish: Math.round(((WEIGHTS.finish * s_finish) / weightedSum) * 1000) / 10,
    };
  }

  return {
    s_uv,
    s_skin,
    s_activity,
    s_concern,
    s_texture,
    s_finish,
    finalScore,
    category,
    isEligible,
    contributions,
  };
}

export function isValidUuid(uuid: string): boolean {
  const pattern = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  return pattern.test(uuid);
}

export function hasDuplicate(arr: string[]): boolean {
  return new Set(arr).size !== arr.length;
}

export function mapSkinTypeCode(codeOrName: string): string {
  const normalized = codeOrName.toLowerCase();
  if (normalized === 'st001' || normalized === 'oily' || normalized === 'berminyak') return 'oily';
  if (normalized === 'st002' || normalized === 'dry' || normalized === 'kering') return 'dry';
  if (normalized === 'st003' || normalized === 'combination' || normalized === 'kombinasi') return 'combination';
  if (normalized === 'st004' || normalized === 'normal') return 'normal';
  if (normalized === 'st005' || normalized === 'sensitive' || normalized === 'sensitif') return 'sensitive';
  return normalized;
}

export function mapConcernCode(codeOrName: string): string {
  const normalized = codeOrName.toLowerCase();
  if (normalized === 'sc001' || normalized === 'acne' || normalized === 'jerawat') return 'acne';
  if (normalized === 'sc002' || normalized === 'hyperpigmentation' || normalized.includes('hiperpigmentasi') || normalized.includes('kusam')) return 'hyperpigmentation';
  if (normalized === 'sc003' || normalized === 'sensitive_irritation' || normalized.includes('irritation') || normalized.includes('sensitif') || normalized.includes('iritasi')) return 'sensitive_irritation';
  if (normalized === 'sc004' || normalized === 'aging' || normalized.includes('penuaan')) return 'aging';
  return normalized;
}

export function paToNumber(pa: string): number {
  const normalized = pa.toUpperCase().replace(/\s+/g, '');
  if (normalized.includes('PA++++')) return 4;
  if (normalized.includes('PA+++')) return 3;
  if (normalized.includes('PA++')) return 2;
  if (normalized.includes('PA+')) return 1;
  return 0;
}

export function comparePaGrade(productPa: string, minimumPa: string): boolean {
  return paToNumber(productPa) >= paToNumber(minimumPa);
}

import { getTodayTarget } from "./constants.ts";

export interface UvDataResult {
  uvIndex: number;
  uvRiskLevel: string;
  spfMinimum: number;
  paMinimum: string;
  usageTimePref: string;
  isForecast: boolean;
  currentLocalHour: number;
  isNight: boolean;
}

export async function getUvDataAndThresholds(
  lat: number,
  lon: number,
  usageTimePrefInput?: string
): Promise<UvDataResult> {
  const openMeteoUrl = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&hourly=uv_index&forecast_days=2&timezone=auto`;
  const openMeteoRes = await fetch(openMeteoUrl);
  if (!openMeteoRes.ok) {
    throw new Error("Gagal mengambil data indeks UV dari Open-Meteo");
  }

  const openMeteoData = await openMeteoRes.json();
  const utcOffsetSeconds = openMeteoData.utc_offset_seconds || 0;
  const uvIndexArr = openMeteoData.hourly?.uv_index;
  if (!uvIndexArr || uvIndexArr.length < 48) {
    throw new Error("Format data UV Open-Meteo tidak valid");
  }

  // Calculate current local hour at coordinate
  const now = new Date();
  const localTime = new Date(now.getTime() + utcOffsetSeconds * 1000);
  const currentLocalHour = localTime.getUTCHours();
  const isNight = currentLocalHour >= 18 || currentLocalHour < 6;

  let uvIndex = 0;
  let isForecast = false;
  let usageTimePref = usageTimePrefInput || 'realtime';

  if (!isNight && usageTimePref === 'realtime') {
    uvIndex = Number(uvIndexArr[currentLocalHour] || 0);
    isForecast = false;
  } else {
    isForecast = true;
    if (usageTimePref === 'realtime') {
      usageTimePref = 'morning'; 
    }

    const tomorrowUv = uvIndexArr.slice(24, 48); // index 24 to 47
    let hourIndices: number[] = [];
    if (usageTimePref === 'morning') {
      hourIndices = [6, 7, 8, 9];
    } else if (usageTimePref === 'afternoon') {
      hourIndices = [10, 11, 12, 13];
    } else if (usageTimePref === 'evening') {
      hourIndices = [14, 15, 16, 17];
    }

    const values = hourIndices.map(h => tomorrowUv[h] || 0);
    uvIndex = Math.max(...values);
  }

  // Target SPF dan PA Berdasarkan Tabel 3 Metodologi
  const target = getTodayTarget(uvIndex);
  const spfMinimum = target.spf;
  const paMinimum = target.pa;

  let uvRiskLevel = 'low';
  if (uvIndex <= 2) uvRiskLevel = 'low';
  else if (uvIndex <= 5) uvRiskLevel = 'moderate';
  else if (uvIndex <= 7) uvRiskLevel = 'high';
  else if (uvIndex <= 10) uvRiskLevel = 'very_high';
  else uvRiskLevel = 'extreme';

  return {
    uvIndex,
    uvRiskLevel,
    spfMinimum,
    paMinimum,
    usageTimePref,
    isForecast,
    currentLocalHour,
    isNight
  };
}

import { isValidUuid, hasDuplicate } from "./utils.ts";

export interface ValidationResult {
  error?: string;
}

export function validateRequestBody(body: any): ValidationResult {
  // --- General Field Validations ---
  if (!body.user_id || !isValidUuid(body.user_id)) {
    return { error: "user_id wajib diisi dengan format UUID yang valid" };
  }

  if (!body.skin_type_id || !isValidUuid(body.skin_type_id)) {
    return { error: "skin_type_id wajib diisi dengan format UUID yang valid" };
  }

  if (body.skin_concern_ids) {
    if (!Array.isArray(body.skin_concern_ids)) {
      return { error: "Format skin_concern_ids harus berupa array" };
    }
    if (body.skin_concern_ids.length > 2) {
      return { error: "Maksimal masalah kulit yang dipilih adalah 2 kategori" };
    }
    if (hasDuplicate(body.skin_concern_ids)) {
      return { error: "Masalah kulit tidak boleh duplikat" };
    }
    for (const id of body.skin_concern_ids) {
      if (!isValidUuid(id)) {
        return { error: "Format skin_concern_id tidak valid" };
      }
    }
  }

  const validActivities = ['indoor', 'outdoor_light', 'outdoor_intense', 'sport', 'swim'];
  if (!body.activity || !validActivities.includes(body.activity)) {
    return { error: `Aktivitas harian wajib dipilih dan harus berupa salah satu dari: ${validActivities.join(', ')}` };
  }

  const validTextures = ['gel', 'cream', 'lotion', 'serum', 'milk', 'watery', 'stick', 'spray', 'mist'];
  if (body.texture_preference && !validTextures.includes(body.texture_preference)) {
    return { error: "Nilai preferensi tekstur tidak valid" };
  }

  const validFinishes = ['matte', 'dewy', 'natural', 'tone_up'];
  if (body.finish_preference && !validFinishes.includes(body.finish_preference)) {
    return { error: "Nilai preferensi hasil akhir tidak valid" };
  }

  const validAllergyStatuses = ['none', 'unknown_ingredient', 'known_ingredient'];
  if (!body.allergy_status || !validAllergyStatuses.includes(body.allergy_status)) {
    return { error: `Status alergi wajib diisi dan harus berupa salah satu dari: ${validAllergyStatuses.join(', ')}` };
  }

  if (body.allergy_status === 'known_ingredient' && (!body.avoided_ingredient_ids || !Array.isArray(body.avoided_ingredient_ids) || body.avoided_ingredient_ids.length === 0)) {
    return { error: "Bahan yang dihindari wajib dipilih jika status alergi diketahui" };
  }

  if (body.avoided_ingredient_ids && Array.isArray(body.avoided_ingredient_ids)) {
    if (hasDuplicate(body.avoided_ingredient_ids)) {
      return { error: "Bahan yang dihindari tidak boleh duplikat" };
    }

    for (const id of body.avoided_ingredient_ids) {
      if (!isValidUuid(id)) {
        return { error: "Format avoided_ingredient_id tidak valid" };
      }
    }
  }

  if (body.latitude === undefined || body.latitude === null || body.longitude === undefined || body.longitude === null) {
    return { error: "Lokasi (latitude & longitude) tidak dapat diakses atau kosong" };
  }

  const lat = Number(body.latitude);
  const lon = Number(body.longitude);

  if (isNaN(lat) || lat < -90 || lat > 90) {
    return { error: "Latitude tidak valid (harus antara -90 dan 90)" };
  }

  if (isNaN(lon) || lon < -180 || lon > 180) {
    return { error: "Longitude tidak valid (harus antara -180 dan 180)" };
  }

  return {};
}

export function validateUsageTimePreference(usageTimePref: any, isNight: boolean): ValidationResult {
  if (isNight) {
    if (!usageTimePref) {
      return { error: "Waktu penggunaan sunscreen wajib dipilih saat malam hari" };
    }

    if (!['morning', 'afternoon', 'evening'].includes(usageTimePref)) {
      return { error: "Waktu penggunaan sunscreen malam hari tidak valid (harus morning, afternoon, atau evening)" };
    }
  } else {
    if (usageTimePref && !['realtime', 'morning', 'afternoon', 'evening'].includes(usageTimePref)) {
      return { error: "Waktu penggunaan sunscreen tidak valid" };
    }
  }
  return {};
}
